use pcb_analyze::extraction::{self,section_cache};use serde_json::{json,Value};
fn run(line:Value,f:Value)->Value{extraction::run(serde_json::from_value(json!({"line":line,"frequencies":f})).unwrap())}
fn replay(line:Value,f:Value,p:Value)->Value{section_cache::replay(serde_json::from_value(json!({"line":line,"frequencies":f})).unwrap(),p)}
fn close(a:&Value,b:&Value){match(a,b){(Value::Number(a),Value::Number(b))=>{let(a,b)=(a.as_f64().unwrap(),b.as_f64().unwrap());assert!((a-b).abs()<=1e-11*b.abs().max(1e-12),"{a} vs {b}");},(Value::Array(a),Value::Array(b))=>{assert_eq!(a.len(),b.len());for(a,b)in a.iter().zip(b){close(a,b)}},(Value::Object(a),Value::Object(b))=>{for(k,a)in a{if let Some(b)=b.get(k){close(a,b)}}},_=>assert_eq!(a,b)}}
#[test]fn pec_length_axis_replay_matches_fresh_fem_and_rejects_changed_geometry_mesh_and_energy(){
 let line=json!({"kind":"microstrip","widthMm":0.3,"copperThicknessMm":0.035,"dielectricHeightMm":0.18,"lengthMm":20.,"material":{"relativePermittivity":4.2,"lossTangent":0.,"state":"explicit PEC control"}});let stored=run(line.clone(),json!([1e8]));assert_eq!(stored["status"],"complete","{stored}");let mut next=line.clone();next["lengthMm"]=json!(40.);let axis=json!([1e8,2e8]);let reused=replay(next.clone(),axis.clone(),stored.clone());assert_eq!(reused["status"],"complete","{reused}");let fresh=run(next.clone(),axis.clone());assert_eq!(fresh["status"],"complete","{fresh}");close(&reused["network"]["parameters"],&fresh["network"]["parameters"]);assert_eq!(reused["fieldReuse"]["assembly"],0);let again=replay(next.clone(),axis.clone(),reused.clone());assert_eq!(again["fieldReuse"]["originalAxisHz"],stored["frequenciesHz"]);assert_eq!(again["fieldReuse"]["fieldPreparationElapsedMs"],stored["elapsedMs"]);
 next["widthMm"]=json!(0.4);assert_eq!(replay(next,axis.clone(),stored.clone())["status"],"rejected");let mut corrupt=stored.clone();corrupt["parameters"]["capacitanceFPerM"][0][0]=json!(-1.);assert_eq!(replay(line.clone(),axis.clone(),corrupt)["status"],"rejected");let request=serde_json::from_value(json!({"line":line,"frequencies":[1e8],"mesh":{"maxNodes":1000}})).unwrap();assert_eq!(section_cache::replay(request,stored)["status"],"rejected");
}
#[test]fn physical_template_loss_integrals_replay_new_frequencies_without_reusing_old_modes(){
 let line=json!({"kind":"stripline","widthMm":1.,"copperThicknessMm":0.035,"bottomDielectricHeightMm":1.,"topDielectricHeightMm":1.,"lengthMm":20.,"bottomMaterial":{"relativePermittivity":4.,"lossTangent":0.01,"state":"constant authored dielectric"},"topMaterial":{"relativePermittivity":4.,"lossTangent":0.01,"state":"constant authored dielectric"},"conductors":{"signal":{"conductivitySM":58e6,"state":"smooth copper"},"referencePlanes":{"bottom":{"thicknessMm":0.035,"material":{"conductivitySM":58e6,"state":"smooth copper"}},"top":{"thicknessMm":0.035,"material":{"conductivitySM":58e6,"state":"smooth copper"}}}}});
 let stored=run(line.clone(),json!([1e9]));assert_eq!(stored["status"],"complete","{stored}");let mut next=line;next["lengthMm"]=json!(30.);let axis=json!([8e8,1.2e9]);let reused=replay(next.clone(),axis.clone(),stored.clone());assert_eq!(reused["status"],"complete","{reused}");let fresh=run(next.clone(),axis.clone());assert_eq!(fresh["status"],"complete","{fresh}");close(&reused["network"]["parameters"],&fresh["network"]["parameters"]);close(&reused["parameters"]["frequencyDependent"]["samples"],&fresh["parameters"]["frequencyDependent"]["samples"]);let mut corrupt=stored;corrupt["lossIntegrals"]["surfaces"][0]["gramPerM"][0][0]=json!(-1.);assert_eq!(replay(next,json!([1e9]),corrupt)["status"],"rejected");
}
#[test]fn arbitrary_polygon_hf_coefficients_replay_with_skin_band_and_psd_guards(){
 use pcb_analyze::extraction::polygon_section::{Contour,Metal,MaterialRegion,Request,LossInput};
 let circle=|r:f64|(0..64).map(|i|{let t=i as f64*std::f64::consts::TAU/64.;[r*t.cos(),r*t.sin()]}).collect::<Vec<_>>();let rect=|r:f64|Contour{outer_m:vec![[-r,-r],[r,-r],[r,r],[-r,r]],holes_m:vec![]};let mut shield=rect(0.001);shield.holes_m.push(circle(0.0008));let domain=rect(0.0012);
 let r=Request{loss:Some(LossInput{frequencies_hz:vec![1e9],conductivity_s_m:vec![58e6;2],minimum_skin_dimensions_m:vec![0.0002;2],dielectric_loss_tangents:vec![0.01],band_hz:[5e8,2e9]}),domain:domain.clone(),conductors:vec![Metal{id:"inner".into(),role:"signal".into(),contour:Contour{outer_m:circle(0.0002),holes_m:vec![]}},Metal{id:"shield".into(),role:"reference".into(),contour:shield}],dielectrics:vec![MaterialRegion{id:"dielectric".into(),relative_permittivity:4.,contour:domain}],max_triangle_area_m2:1e-9,max_nodes:30000,max_seconds:120.,max_memory_mib:256};
 let line=json!({"kind":"polygon-section","geometry":r,"lengthMm":10.});let stored=run(line.clone(),json!([1e9]));assert_eq!(stored["status"],"complete","{stored}");let mut next=line;next["lengthMm"]=json!(20.);let axis=json!([8e8,1.2e9]);let reused=replay(next.clone(),axis.clone(),stored.clone());assert_eq!(reused["status"],"complete","{reused}");let fresh=run(next.clone(),axis.clone());assert_eq!(fresh["status"],"complete","{fresh}");close(&reused["network"]["parameters"],&fresh["network"]["parameters"]);close(&reused["frequencyDependent"]["samples"],&fresh["frequencyDependent"]["samples"]);assert_eq!(replay(next.clone(),json!([1e8]),stored.clone())["status"],"rejected");let mut corrupt=stored;corrupt["frequencyDependent"]["regionalCapacitanceFPerM"][0][0][0]=json!(-1.);assert_eq!(replay(next,axis,corrupt)["status"],"rejected");
}
